function flatten(nested) {
    const result = [];
    const stack = [...nested].reverse();
    while (stack.length) {
        const item = stack.pop();
        if (Array.isArray(item)) stack.push(...[...item].reverse());
        else result.push(item);
    }
    return result;
}

